parts.text:
[
  {
    "statement": "No information could be found about the effects of using precision agriculture techniques on soil invertebrate communities.",
    "citations": []
  }
]

[
  {
    "statement": "Agri-environment schemes that pay farmers for conservation measures have shown varied effects on European wildlife.",
    "citations": []
  },
  {
    "statement": "For birds, some studies found increases in population sizes or densities on sites with agri-environment schemes.",
    "citations": [
      "700",
      "172"
    ]
  },
  {
    "statement": "Other studies on birds found negative or no effects from agri-environment schemes.",
    "citations": [
      "700",
      "172"
    ]
  },
  {
    "statement": "Specially-designed agri-environment schemes have led to population increases for cirl buntings, corncrakes and Eurasian thick-knees.",
    "citations": [
      "172"
    ]
  },
  {
    "statement": "The impact of agri-environment schemes on wild bees is mixed.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "Some European trials of agri-environment schemes showed enhanced diversity and abundance of wild bees.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "Other studies, including landscape-scale studies in the UK, found no enhancements in wild bee diversity and abundance from agri-environment schemes.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "For butterflies and moths, the evidence of the impact of agri-environment schemes is more consistently positive.",
    "citations": []
  },
  {
    "statement": "Multiple studies in the UK, Switzerland, and Sweden reported higher species richness or diversity of butterflies and moths on lands in agri-environment schemes.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "A majority of studies found higher abundance of butterflies and moths on lands in agri-environment schemes.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Some studies noted that the abundance of butterflies and moths was similar or lower on lands in agri-environment schemes compared to conventionally managed or unmanaged lands.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Specific farming practices like undersowing spring cereals with legumes have shown higher butterfly richness in some contexts.",
    "citations": [
      "3926"
    ]
  },
  {
    "statement": "In other contexts, the practice of undersowing spring cereals with legumes has not increased butterfly richness.",
    "citations": [
      "3926"
    ]
  },
  {
    "statement": "The effects of agri-environment schemes on other wildlife are also variable.",
    "citations": []
  },
  {
    "statement": "Payments to farmers in Denmark and Sweden helped create amphibian breeding habitat and increase amphibian populations.",
    "citations": [
      "818"
    ]
  },
  {
    "statement": "Managed ditches in the Netherlands had higher numbers of amphibian species.",
    "citations": [
      "818"
    ]
  },
  {
    "statement": "For mammals, agri-environment schemes were associated with increased brown hare density in one UK region but not another.",
    "citations": [
      "2387"
    ]
  },
  {
    "statement": "Agri-environment schemes had no effect on Irish hare numbers in Northern Ireland.",
    "citations": [
      "2387"
    ]
  },
  {
    "statement": "Small mammal abundance increased in field margins managed under agri-environment schemes in the UK.",
    "citations": [
      "2387"
    ]
  },
  {
    "statement": "Studies on bats in the UK found that agri-environment schemes did not lead to significant increases in bat activity.",
    "citations": [
      "962"
    ]
  },
  {
    "statement": "One study on bats in the UK recorded lower bat activity on lands in agri-environment schemes.",
    "citations": [
      "962"
    ]
  }
]

[
  {
    "statement": "No information regarding the cost-effectiveness of any method for increasing invertebrate diversity on arable farms is available.",
    "citations": []
  },
  {
    "statement": "Several methods for increasing invertebrate diversity have been studied.",
    "citations": []
  },
  {
    "statement": "Converting to organic farming may lead to a greater species richness of butterflies and moths on arable farms.",
    "citations": [
      "3907"
    ]
  },
  {
    "statement": "Converting to organic farming may lead to a greater abundance of butterflies and moths on arable farms.",
    "citations": [
      "3907"
    ]
  },
  {
    "statement": "Reducing field size can increase the abundance of butterflies and moths.",
    "citations": [
      "3974"
    ]
  },
  {
    "statement": "Reducing field size can increase species richness in some cases.",
    "citations": [
      "3974"
    ]
  },
  {
    "statement": "Providing buffer strips alongside water courses has been shown to have a positive influence on invertebrate diversity.",
    "citations": [
      "120"
    ]
  },
  {
    "statement": "Providing buffer strips alongside water courses has been shown to have a positive influence on invertebrate abundance.",
    "citations": [
      "120"
    ]
  },
  {
    "statement": "Planting field margins with a diverse mix of plant species has been found to increase the activity of certain bat species.",
    "citations": [
      "1941"
    ]
  },
  {
    "statement": "Certain bat species prey on insects.",
    "citations": [
      "1941"
    ]
  }
]

[
  {
    "statement": "No relevant documents were found that directly evaluated the impact of precision agriculture techniques, such as GPS-guided variable rate fertilizer application, on soil invertebrate populations.",
    "citations": []
  },
  {
    "statement": "Several studies have investigated the effects of reducing or changing fertilizer types on invertebrates.",
    "citations": []
  },
  {
    "statement": "Five studies found positive effects of reducing or stopping fertilizer applications on invertebrates.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "Four studies found that reducing or stopping fertilizer inputs had no, or no consistent, effects on some invertebrates.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "Two studies from the UK found that plots where fertilizer inputs were not reduced tended to have higher earthworm biomass or abundance.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "In permanent grasslands, six studies found that stopping fertilizer inputs resulted in a higher abundance or species richness of some or all invertebrates studied.",
    "citations": [
      "694"
    ]
  },
  {
    "statement": "One review found that densities of some invertebrates were higher in unfertilized plots.",
    "citations": [
      "694"
    ]
  },
  {
    "statement": "Another review found no clear effect of reducing fertilizer inputs on the density of soil-dwelling invertebrates.",
    "citations": [
      "694"
    ]
  },
  {
    "statement": "One study found lower invertebrate abundance on plots with reduced fertilizer inputs, although the differences were not significant.",
    "citations": [
      "694"
    ]
  },
  {
    "statement": "One study found fewer nematodes in plots with organic fertilizer compared to inorganic fertilizer.",
    "citations": [
      "1366"
    ]
  },
  {
    "statement": "Another study found fewer mites in plots with organic fertilizer compared to inorganic fertilizer.",
    "citations": [
      "1366"
    ]
  },
  {
    "statement": "The study that found fewer mites in organic fertilizer plots noted that organic fertilizer plots had more microbial biomass.",
    "citations": [
      "1366"
    ]
  }
]
